sys_script_include.script:
var InsuranceUtils = Class.create();
InsuranceUtils.prototype = {
    initialize: function() {},

    sys: function(id) {
        var pat = new GlideRecord('u_patient_record');
        pat.addQuery('u_number', id);
        pat.query();
        pat.next();
        var sys = pat.getUniqueValue();
        return sys;
    },
    //Fetch insurance details by patient ID.
    fetchinsurancedetailpatientid: function(id) {
        var sysid = this.sys(id);
        var insurance = new GlideRecord('u_insurance');
        insurance.addQuery('u_patient_id', sysid);
        insurance.query();
        return insurance;
    },
    //Check if an insurance policy is active. 
    checkactive: function(id) {
        var insurance = new GlideRecord('u_insurance');
        insurance.addQuery('number', id);
        insurance.query()
        if (insurance.next()) {
            if (insurance.u_status == 'active') {
                return true;
            } else {
                return false;
            }
        } else {
            return "Record Not Found";
        }
    },
    //Fetch insurance policy by ID.
    fetchdetails: function(id) {
        var ins = new GlideRecord('u_insurance');
        ins.addQuery('number', id);
		ins.query();
        return ins;

    },
	//Fetch insurance policies by provider
	fetchbyprovider:function(providername)
	{
		var pro = new GlideRecord('u_insurance');
		pro.addQuery('u_provider',providername);
		pro.query();
		return pro;
	},




    type: 'InsuranceUtils'
};
